package com.example.inventory.dao; import com.example.inventory.models.Item;import java.sql.*;import java.util.*;public class ItemDao{private final Connection c;public ItemDao(Connection c){this.c=c;}public void addItem(Item i)throws SQLException{if(i.getQuantity()<0)throw new IllegalArgumentException("Quantity cannot be negative");try(PreparedStatement p=c.prepareStatement("INSERT INTO items(name,quantity,vendor_id) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,i.getName());p.setInt(2,i.getQuantity());if(i.getVendorId()>0)p.setInt(3,i.getVendorId());else p.setNull(3,Types.INTEGER);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())i.setId(r.getInt(1));}}}public void updateItem(Item i)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE items SET name=?,quantity=?,vendor_id=? WHERE id=?")){p.setString(1,i.getName());p.setInt(2,i.getQuantity());if(i.getVendorId()>0)p.setInt(3,i.getVendorId());else p.setNull(3,Types.INTEGER);p.setInt(4,i.getId());if(p.executeUpdate()==0)throw new SQLException("Item not found: "+i.getId());}}public Item getItem(int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id,name,quantity,COALESCE(vendor_id,0) FROM items WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?new Item(r.getInt(1),r.getString(2),r.getInt(3),r.getInt(4)):null;}}}public List<Item> getAllItems()throws SQLException{List<Item>o=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,quantity,COALESCE(vendor_id,0) FROM items ORDER BY id")){while(r.next())o.add(new Item(r.getInt(1),r.getString(2),r.getInt(3),r.getInt(4)));}return o;}public void deleteItem(int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("DELETE FROM items WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}}